public class UrlBuilderTest {

    @Test
    public void urlBuilder_construction_withInputUrl() {
        URL inputUrl = new URL("https://example.com");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        assert urlBuilder != null;
    }

    @Test
    public void urlBuilder_buildMethod_returnsConstructedUrl() throws MalformedURLException, URISyntaxException {
        URL inputUrl = new URL("https://example.com/path");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        URL constructedUrl = urlBuilder.build();
        assertEquals(inputUrl.getProtocol(), constructedUrl.getProtocol());
    }

    @Test
    public void urlBuilder_buildMethod_returnsConstructedUrlWithQuery() throws MalformedURLException, URISyntaxException {
        URL inputUrl = new URL("https://example.com/path?a=1&b=2");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        URL constructedUrl = urlBuilder.build();
        assertEquals(URLEncoder.encode("a=1&b=2", DataUtil.UTF_8), URLEncoder.encode(urlBuilder.appendKeyVal(Connection.KeyVal.of("a", "1")).appendKeyVal(Connection.KeyVal.of("b", "2")).encode(), DataUtil.UTF_8));
    }

    @Test
    public void urlBuilder_appendKeyValue_returnsString() {
        Connection.KeyVal kv = Connection.KeyVal.of("key", "value");
        UrlBuilder urlBuilder = new UrlBuilder(new URL("https://example.com"));
        String result = urlBuilder.appendKeyVal(kv).encode();
        assertNotNull(result);
        assertTrue(result.contains("key=value"));
    }

    @Test
    public void urlBuilder_appendKeyValue_returnsStringWithNonASCIIKey() {
        Connection.KeyVal kv = Connection.KeyVal.of(IDN.toUTF8("ä"), "value");
        UrlBuilder urlBuilder = new UrlBuilder(new URL("https://example.com"));
        String result = urlBuilder.appendKeyVal(kv).encode();
        assertNotNull(result);
        assertTrue(result.contains("ä=value"));
    }

    @Test
    public void urlBuilder_appendKeyValue_throwsUnsupportedEncodingException() {
        Connection.KeyVal kv = Connection.KeyVal.of("key", "value");
        UrlBuilder urlBuilder = new UrlBuilder(new URL("https://example.com"));
        assertThrows(UnsupportedEncodingException.class, () -> urlBuilder.appendKeyVal(kv).encode());
    }
}
